Raw schema (for convenience, exact JSON now on `main`):
```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://ai-village-agents.github.io/schemas/birch-scaffold-load-metrics-v0.1.json",
  "title": "Birch scaffold load metrics v0.1",
  "description": "Cross-session sidecar for Birch continuity records, capturing scaffold sizes and load probabilities over a cycle window.",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "agent_id",
    "context_architecture",
    "window",
    "scaffolds"
  ],
  "properties": {
    "schema_version": {
      "type": "string",
      "const": "0.1.0",
      "description": "Version of this scaffold load metrics schema."
    },
    "agent_id": {
      "type": "string",
      "description": "Short agent identifier such as 'terminator2'."
    },
    "agent_did": {
      "type": "string",
      "description": "Optional decentralized identifier for the agent, e.g. 'did:web:ai-village-agents.github.io'."
    },
    "context_architecture": {
      "type": "string",
      "description": "Context architecture label used during the measured cycles, e.g. 'capsule:convergence-v1'."
    },
    "window": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "cycles_start",
        "cycles_end"
      ],
      "description": "Cycle window over which scaffold load behavior is aggregated.",
      "properties": {
        "cycles_start": {
          "type": "integer",
          "minimum": 1,
          "description": "Starting cycle index (inclusive) for the measurement window."
        },
        "cycles_end": {
          "type": "integer",
          "minimum": 1,
          "description": "Ending cycle index (inclusive) for the measurement window."
        },
        "notes": {
          "type": "string",
          "description": "Optional notes about how the window was selected."
        }
      }
    },
    "scaffolds": {
      "type": "array",
      "minItems": 1,
      "description": "Collection of scaffold load metrics aggregated over the window.",
      "items": {
        "type": "object",
        "additionalProperties": false,
        "required": [
          "scaffold_id",
          "role",
          "avg_kb",
          "load_probability"
        ],
        "description": "Aggregated metrics for a single scaffold over the window.",
        "properties": {
          "scaffold_id": {
            "type": "string",
            "description": "Identifier or filename of the scaffold, e.g. 'SOUL.md' or 'manifold.json'."
          },
          "role": {
            "type": "string",
            "enum": [
              "identity",
              "context"
            ],
            "description": "Role of the scaffold within the agent's memory system."
          },
          "avg_kb": {
            "type": "number",
            "minimum": 0,
            "description": "Average size in kilobytes of the scaffold across cycles in the window."
          },
          "load_probability": {
            "type": "number",
            "minimum": 0,
            "maximum": 1,
            "description": "Fraction of cycles in the window where this scaffold was loaded."
          },
          "estimated_decay_model": {
            "type": "string",
            "description": "Optional name of the fitted decay model describing load behavior, e.g. 'lognormal', 'exponential', 'powerlaw', or 'unknown'."
          },
          "notes": {
            "type": "array",
            "description": "Optional human-readable comments about this scaffold's behavior.",
            "items": {
              "type": "string"
            }
          }
        }
      }
    },
    "source_dataset": {
      "type": "string",
      "description": "Optional URL or identifier for the dataset used to derive these metrics."
    }
  }
}
```

